+interface TestEvents {
+  test: (value: string) => void;
+  numeric: (n: number) => void;
+  empty: () => void;
+}
+
+describe("EventBus", () => {
+  // -----------------------------------------------------------------------
+  // Basic on/off/emit
+  // -----------------------------------------------------------------------
+
+  it("emits to subscribed handlers", () => {
+    const bus = new EventBus<TestEvents>();
+    const fn = vi.fn();
+    bus.on("test", fn);
+    bus.emit("test", "hello");
+    expect(fn).toHaveBeenCalledWith("hello");
+  });
+
+  it("does not emit to unsubscribed handlers", () => {
+    const bus = new EventBus<TestEvents>();
+    const fn = vi.fn();
+    bus.on("test", fn);
+    bus.off("test", fn);
+    bus.emit("test", "hello");
+    expect(fn).not.toHaveBeenCalled();
+  });
+
+  it("supports multiple handlers for the same event", () => {
+    const bus = new EventBus<TestEvents>();
+    const a = vi.fn();
+    const b = vi.fn();
+    bus.on("test", a);
+    bus.on("test", b);
+    bus.emit("test", "x");
+    expect(a).toHaveBeenCalledWith("x");
+    expect(b).toHaveBeenCalledWith("x");
+  });
+
+  it("supports multiple arguments per event", () => {
+    const bus = new EventBus<{ multi: (a: string, b: number) => void }>();
+    const fn = vi.fn();
+    bus.on("multi", fn);
+    bus.emit("multi", "test", 42);
+    expect(fn).toHaveBeenCalledWith("test", 42);
+  });
